/bin/bash -lc "bash -lc '
set -euo pipefail
mapfile -t reps < <(node -e '
const reps = new Map();
for (let a = 1; a <= 5; a += 1) {
  for (let b = 1; b <= 5; b += 1) {
    for (let c = 1; c <= 5; c += 1) {
      for (let d = 1; d <= 5; d += 1) {
        for (let e = 1; e <= 5; e += 1) {
          const values = [a, b, c, d, e];
          const seen = new Map();
          let next = 1;
          const key = values.map((value) => {
            if ("'!seen.has(value)) {
              seen.set(value, next);
              next += 1;
            }
            return seen.get(value);
          }).join(",");
          if (!reps.has(key)) {
            reps.set(key, values);
          }
        }
      }
    }
  }
}
for (const values of reps.values()) {
  console.log(values.join(" "));
}
'"')
for rep in \""'${reps[@]}"; do
  read -r a b c d e <<< "$rep"
  expected=$(/workspace/dataset/test10_executable --a "$a" --b "$b" --c "$c" --d "$d" --e "$e")
  actual=$(node /output/test10.mjs --a "$a" --b "$b" --c "$c" --d "$d" --e "$e")
  if [ "$expected" != "$actual" ]; then
    echo "REP_MISMATCH: $rep"
    echo "EXPECTED<<EOF"
    printf '"'%s\\n' \""'$expected"
    echo "EOF"
    echo "ACTUAL<<EOF"
    printf '"'%s\\n' \""'$actual"
    echo "EOF"
    exit 1
  fi
done
normalize_name() { sed "s/test10_executable/test10.mjs/g"; }
compare_case() {
  local label="$1"
  shift
  set +e
  expected=$(/workspace/dataset/test10_executable "$@" 2>&1)
  expected_code=$?
  actual=$(node /output/test10.mjs "$@" 2>&1)
  actual_code=$?
  set -e
  expected=$(printf '"'%s' \""'$expected" | normalize_name)
  if [ "$expected_code" -ne "$actual_code" ] || [ "$expected" != "$actual" ]; then
    echo "CLI_MISMATCH: $label"
    echo "EXPECTED_CODE=$expected_code ACTUAL_CODE=$actual_code"
    echo "EXPECTED<<EOF"
    printf '"'%s\\n' \""'$expected"
    echo "EOF"
    echo "ACTUAL<<EOF"
    printf '"'%s\\n' \""'$actual"
    echo "EOF"
    exit 1
  fi
}
compare_case help --help
compare_case short_help -h
compare_case missing --a 1 --b 2 --c 3 --d 4
compare_case invalid_int --a x --b 2 --c 3 --d 4 --e 5
compare_case expected_one_argument --a --b 2 --c 3 --d 4 --e 5
compare_case unrecognized --a 1 --b 2 --c 3 --d 4 --e 5 --z 6
compare_case inline_equals --a=1 --b=2 --c=3 --d=4 --e=5
compare_case duplicate --a 1 --a 2 --b 3 --c 4 --d 5 --e 6
echo OK
'"'"

